export interface SketchPanelArt {
  img: string;
  bubbles?: SketchBubble[];
  when?: string;
  whenPos?: "tl" | "tr";
  stage?: string;
  title?: string;
  caption?: string;
  term?: { name: string; def: string };
}
export interface SketchComicMeta { title: string; lead?: string; narrator?: string; cta?: string }

